import sendEmail from "mail-send-v1";

/**
 * Primary product path — user-facing notifications.
 * Migrate mail-send-v1 → mail-send-v2 structured send().
 *
 * v1 helpers return the bare message id string (`SendResult.id`).
 * v2 helpers should return the full `SendResult` (`messageId` + `accepted`) —
 * callers one hop away (see onboarding.ts) must adapt.
 */
export async function notifyUser(
  email: string,
  name: string
): Promise<string> {
  const r = await sendEmail(
    email,
    "noreply@morphapi.demo",
    "Welcome",
    `Hi ${name}, thanks for signing up.`
  );
  return r.id;
}

export async function notifyPasswordReset(
  email: string,
  token: string
): Promise<string> {
  const r = await sendEmail(
    email,
    "security@morphapi.demo",
    "Reset your password",
    `Use this token: ${token}`
  );
  return r.id;
}

fixtures/mail-client-v1/src/notify.ts.after:
import { send } from "mail-send-v2";

/**
 * Primary product path — user-facing notifications.
 * Migrate mail-send-v1 → mail-send-v2 structured send().
 *
 * v1 helpers return the bare message id string (`SendResult.id`).
 * v2 helpers should return the full `SendResult` (`messageId` + `accepted`) —
 * callers one hop away (see onboarding.ts) must adapt.
 */
export async function notifyUser(
  email: string,
  name: string
): Promise<string> {
  const r = await send({ to: email, from: "noreply@morphapi.demo", subject: "Welcome", content: `Hi ${name}, thanks for signing up.` });
  return r.messageId;
}

export async function notifyPasswordReset(
  email: string,
  token: string
): Promise<string> {
  const r = await send({ to: email, from: "security@morphapi.demo", subject: "Reset your password", content: `Use this token: ${token}` });
  return r.messageId;
}

